public abstract record Pagamento;
public record Pix(string Chave) : Pagamento;
public record Cartao(string Bandeira, int Parcelas) : Pagamento;

decimal Taxa(Pagamento p) => p switch
{
    Pix => 0m,
    Cartao { Parcelas: 1 } => 0.02m,
    Cartao { Parcelas: > 1 and <= 6 } => 0.04m,
    Cartao => 0.06m,
    _ => throw new ArgumentOutOfRangeException(nameof(p)),
};

var a = new Cartao("visa", 3);
var b = a with { Parcelas = 1 };
Console.WriteLine(a == new Cartao("visa", 3)); // True

public async Task<decimal> BuscarCotacaoAsync(string moeda, CancellationToken ct)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
    cts.CancelAfter(TimeSpan.FromSeconds(5));

    var resposta = await _http.GetFromJsonAsync<Cotacao>(
        $"/cotacoes/{moeda}", cts.Token);

    return resposta?.Valor ?? throw new InvalidOperationException("Cotação vazia");
}

